    jQuery(function($) {
        const mobileLangButton = $('.wpml-ls-item-legacy-dropdown-click .wpml-ls-item-toggle');
        const mobileLangMenu = $('.wpml-ls-item-legacy-dropdown-click .js-wpml-ls-sub-menu');

        const langMap = {
            'en': 'EN',
            'es': 'ES',
            'ru': 'РУ',
            'ko': 'KO',
            'zh-hans': '简体',
            'zh-hant': '繁體',
            'ar': 'AR',
            'hi': 'HI',
            'bn': 'BN',
            'uz': 'UZ',
            'ur': 'UR'
        };

        const currentLangItem = $('.widget_icl_lang_sel_widget .wpml-ls-current-language');
        $.each(langMap, function(code, short) {
            if (currentLangItem.hasClass('wpml-ls-item-' + code)) {
                currentLangItem.find('.js-wpml-ls-item-toggle')
                    .append('<span class="lang-short">' + short + '</span>');
            }
        });

        $('.widget_icl_lang_sel_widget .wpml-ls-sub-menu .wpml-ls-item').each(function() {
            const $li = $(this);
            $.each(langMap, function(code, short) {
                if ($li.hasClass('wpml-ls-item-' + code)) {
                    $li.find('a').append('<span class="lang-short">' + short + '</span>');
                }
            });
        });


        if (mobileLangButton.length) {
            mobileLangButton.on('click', function(e) {
                e.preventDefault();

                $(this).toggleClass('active-an');

                mobileLangMenu.toggleClass('lang-menu-active');

                if (mobileLangMenu.hasClass('lang-menu-active')) {
                    $(document).on('click.langMenu', function(event) {
                        if (!$(event.target).closest('.wpml-ls-item-legacy-dropdown-click').length) {
                            mobileLangMenu.removeClass('lang-menu-active');
                            mobileLangButton.removeClass('active-an');
                            $(document).off('click.langMenu');
                        }
                    });
                } else {
                    $(document).off('click.langMenu');
                }
            });
        }
    });





    $(window).on('resize', function(){
        var win = $(window).width();
        if (win >= 992) {
            //console.log('test');
            $('.c-main-menu').removeClass('active-an');
            $('.c-main-menu').removeClass('menu-active');
            $('.o-header').removeClass('open');
            $('body').removeClass('u-overflow');
            $('.navBurger').removeClass('active-an');
        }
    });

    $(window).scroll(function(){
        var headerOffset = $('.o-header').offset();
        var headerTopOffset = headerOffset.top;
        var topMenuHeight = $('.o-header__top').outerHeight();
        var stickyMenuOffset = headerTopOffset + topMenuHeight;
        var stickyMenuHeight = $('.o-header__main').outerHeight();
        var stickyMenu = $('.o-header__main');
        var scroll = $(window).scrollTop();

        if (scroll >= stickyMenuOffset) {
            stickyMenu.addClass('fixed');
            $('.o-header').css('margin-bottom', (stickyMenuHeight));
        } else {
            stickyMenu.removeClass('fixed');
            $('.o-header').css('margin-bottom', (0));
        }
      });

